    target_x = sandbox.TRACK_CENTER_X  # Use the environment's track center

    # Corrected coefficients with proper signs and scaled for new force limit
    force = (4.67 * theta) + (1.17 * omega) + (0.069 * (x - target_x)) + (0.172 * v)
